"""Post-hoc audit only: frozen predictor residuals and native read equations."""
import sys,json
from pathlib import Path
import numpy as np
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_long_materials as P
from shared.dist_protocol.mechanism_trace import unbits,file_sha
def main():
    import torch
    data=P.read(P.OUT/'documents.json');a=P.read(P.OUT/'analysis.json');pred=np.load(P.OUT/'paired-predictions.npz');rows=[];reconstruction=[]
    for l in range(36):
        ix=[i for i,u in enumerate(data['units']) if u['layer']==l];pp=np.load(P.OUT/f'predictor-L{l:02d}.npz');param=np.load(P.OUT/f'parameters-L{l:02d}.npz')
        fields={k:np.load(P.OUT/f'L{l:02d}-{k}.npy',mmap_mode='r') for k in ['G','V','A']};gamma=torch.from_numpy(unbits(param['gamma']))
        unit_errors={j:{'G':[],'V':[],'A':[]} for j in range(len(ix))}
        for fold in [0,1,2]:
            for pole in ['Gpos','Gneg','Apos','Aneg']:
                z=np.load(P.OUT/f'pool-{fold}-L{l:02d}-{pole}.npz');h=torch.from_numpy(unbits(z['h']));rms=(h.square().mean(-1,keepdim=True)+1e-6).sqrt()
                normalized=(h/rms).to(torch.bfloat16)*gamma.to(torch.bfloat16);normalized=normalized.float().numpy()
                g=np.einsum('kud,ud->ku',normalized,unbits(param['gate']));v=np.einsum('kud,ud->ku',normalized,unbits(param['up']))
                for j,ii in enumerate(ix):
                    di=z['doc'][:,j];pos=z['position'][:,j];actual={k:unbits(vv[di,pos,j]) for k,vv in fields.items()}
                    ag=torch.from_numpy(actual['G']).to(torch.bfloat16);av=torch.from_numpy(actual['V']).to(torch.bfloat16)
                    product=(torch.nn.functional.silu(ag)*av).float().numpy()
                    for k,prediction in [('G',g[:,j]),('V',v[:,j]),('A',product)]:
                        unit_errors[j][k].extend((prediction-actual[k]).tolist())
        for j,ii in enumerate(ix):
            errors=unit_errors[j];reconstruction.append({'layer':l,'unit':data['units'][ii]['unit'],'n':len(errors['G']),
                'G_RMSE':float(np.sqrt(np.mean(np.square(errors['G'])))),'V_RMSE':float(np.sqrt(np.mean(np.square(errors['V'])))),
                'A_max_abs':float(np.max(np.abs(errors['A']))),'A_exact_fraction':float(np.mean(np.asarray(errors['A'])==0))})
        for split in ['confirm','lockbox']:
            baseline=np.stack([pp['means'][p['token_id']]+pp['position_mean'][p['position']//64] for p in data['pairs'][split]])
            truth=pred[split+'_actual'][:,:,ix];prediction=pred[split+'_prediction'][:,:,ix];shuffle=pred[split+'_shuffle'][:,:,ix]
            mse0=((truth-baseline[:,None])**2).mean((0,1));mse=((truth-prediction)**2).mean((0,1));msen=((truth-shuffle)**2).mean((0,1))
            for j,ii in enumerate(ix):rows.append({'layer':l,'unit':data['units'][ii]['unit'],'selection':data['units'][ii]['selection'],'split':split,
                'baseline_MSE':float(mse0[j]),'context_MSE':float(mse[j]),'shuffle_MSE':float(msen[j]),'relative_MSE_reduction':float(1-mse[j]/max(1e-12,mse0[j]))})
    d={'kind':'real','run_id':P.RUN,'scope':'Post-hoc frozen-output diagnostics; no threshold or primary verdict changed; true h read-equation checks are not a graph prediction benchmark',
        'reader_formula':'RMSNorm(h)*gamma dotted with actual gate/up rows; BF16 casting reproduced, FP32 sum audited; rms_norm_eps=1e-6',
        'rows':rows,'reconstruction':reconstruction,'A_exact_fraction':float(np.mean([r['A_exact_fraction'] for r in reconstruction])),
        'A_max_abs':max(r['A_max_abs'] for r in reconstruction),'provenance':a['provenance'],'script_sha256':file_sha(__file__)}
    P.save(P.OUT/'diagnostics.json',d);print(json.dumps({k:d[k] for k in ['A_exact_fraction','A_max_abs','scope']}))
if __name__=='__main__':main()

"""Input-only prefix features and exact matched-pair audit, no future states."""
import numpy as np
CAT=['CJK','Latin','digit','space','punct','newline','comma','period','bracket','quote','operator','byte_fragment']
FEATURES=[f'prior{w}_{c}' for w in [16,64,256,512] for c in CAT]+[f'previous{k}_{c}' for k in range(1,5) for c in CAT]
def categories(tok,size=151936):
    import unicodedata
    x=np.zeros((size,len(CAT)),np.float32)
    for i in range(size):
        t=tok.decode([i]);x[i]=[any('\u4e00'<=c<='\u9fff' for c in t),any(c.isascii() and c.isalpha() for c in t),any(c.isdecimal() for c in t),
            bool(t) and t.isspace(),any(unicodedata.category(c).startswith('P') for c in t),'\n' in t,any(c in ',，、' for c in t),
            any(c in '.。;；:：' for c in t),any(c in '()[]{}（）【】' for c in t),any(c in '\"\'“”‘’' for c in t),
            any(c in '+-*/=<>|&%^' for c in t),'�' in t]
    return x
def prefix_features(ids,cat):
    v=cat[np.asarray(ids)];n=len(v);p=np.arange(n);s=np.vstack([np.zeros((1,len(CAT)),np.float32),np.cumsum(v,axis=0)])
    columns=[(s[p]-s[np.maximum(0,p-w)])/np.maximum(1,np.minimum(p,w))[:,None] for w in [16,64,256,512]]
    columns += [v[np.maximum(0,p-k)]*(p>=k)[:,None] for k in range(1,5)]
    return np.concatenate(columns,axis=1).astype(np.float32)
def mcnemar(base,model):
    from scipy.stats import binomtest
    b=np.asarray(base,bool);m=np.asarray(model,bool);gain=int((~b&m).sum());loss=int((b&~m).sum())
    return {'n':len(b),'baseline_accuracy':float(b.mean()),'accuracy':float(m.mean()),'delta':float(m.mean()-b.mean()),
        'gains':gain,'losses':loss,'p':float(binomtest(gain,gain+loss,.5,alternative='greater').pvalue) if gain+loss else 1.}

"""Real single-GPU natural long-context collection; selected raw arrays lossless."""
import json,sys,time,subprocess,shutil
from pathlib import Path
import numpy as np
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_long_materials as P
from shared.dist_protocol.mechanism_trace import GpuLease,digest,file_sha
from shared.dist_protocol.natural_register_runner import snapshot
from deploy.research_library import Library
def status(stage,state='done',**kw):
    path=P.PUBLIC/'00-progress.research.json';d=P.read(path) if path.exists() else {'schema':'research_workpackage.v1','kind':'real','run_id':P.RUN,'title':'原生MLP长语料 · 全层普查与432随机单元留出说明书','stages':{}}
    d['stages'][stage]={'state':state,'time':time.time(),**kw};d['updated_at']=time.time();P.save(path,d,False)
    Library(P.ROOT/'distributed_data/research_library').ingest(d,str(path.relative_to(P.ROOT)),kind='local_report');print(json.dumps({'stage':stage,'state':state,**kw},ensure_ascii=False),flush=True)

def main():
    import torch
    from transformers import AutoTokenizer,AutoModelForCausalLM
    data=P.read(P.OUT/'documents.json');pr=P.read(P.PUBLIC/'prereg.research.json');docs=data['docs'];units=data['units'];raw=np.load(P.OUT/'input-tokens.npy',mmap_mode='r')
    files=['tests/glm5/native_mlp_long_materials.py','tests/glm5/native_mlp_long_features.py','tests/glm5/native_mlp_long_run.py','tests/glm5/native_mlp_long_analyze.py']
    freeze={'run_id':P.RUN,'prereg_sha256':digest(pr),'dependencies':{n:file_sha(P.ROOT/n) for n in files},'documents_sha256':file_sha(P.OUT/'documents.json'),'model_snapshot':pr['model_snapshot']}
    P.save(P.OUT/'execution-freeze.json',freeze)
    prov={'git_sha':subprocess.check_output(['git','-c',f'safe.directory={P.ROOT.as_posix()}','rev-parse','HEAD'],text=True).strip(),'git_dirty':True,'model_path':str(P.MODEL),'model_revision':pr['model_snapshot'],'seed':P.SEED}
    with GpuLease():
        assert torch.cuda.is_available() and snapshot(P.MODEL)==pr['model_snapshot'];assert shutil.disk_usage(P.OUT).free>50*2**30
        torch.set_num_threads(4);torch.manual_seed(P.SEED);started=time.time()
        model=AutoModelForCausalLM.from_pretrained(P.MODEL,local_files_only=True,dtype=torch.bfloat16,device_map='cuda',attn_implementation='sdpa').eval().requires_grad_(False)
        specs={l:[r['unit'] for r in units if r['layer']==l] for l in range(36)}
        mm={l:{key:np.lib.format.open_memmap(P.OUT/f'L{l:02d}-{key}.npy',mode='w+',dtype=np.uint16,shape=(2048,1024,len(specs[l]))) for key in ['G','V','A']} for l in specs}
        hidden=np.lib.format.open_memmap(P.OUT/'hidden_last.npy',mode='w+',dtype=np.uint16,shape=(2048,37,2560))
        sums=torch.zeros((3,36,3,9728),dtype=torch.float64,device='cuda');squares=torch.zeros_like(sums)
        mins=torch.full_like(sums,float('inf'));maxs=torch.full_like(sums,float('-inf'));regimes=torch.zeros((3,36,9728,4),dtype=torch.int64,device='cuda')
        hsum=torch.zeros((3,36,2560),dtype=torch.float64,device='cuda');hnorm=torch.zeros((3,36),dtype=torch.float64,device='cuda')
        count=np.zeros(3,np.int64);ctx={};pools={};handles=[];K=64
        for l in range(36):
            n=len(specs[l])
            for fold in range(3):
                for pole in ['Gpos','Gneg','Apos','Aneg']:
                    pools[(fold,l,pole)]={'value':np.full((K,n),-np.inf,np.float32),'doc':np.full((K,n),-1,np.int32),'position':np.zeros((K,n),np.int16),
                        'h':np.zeros((K,n,2560),np.uint16)}
        def bits(x):return x.detach().contiguous().view(torch.uint16).cpu().numpy()
        def pool_update(fold,l,pole,values,positions,h):
            pool=pools[(fold,l,pole)];sign=-1 if pole.endswith('neg') else 1
            values=(values*sign).float().cpu().numpy();positions=positions.cpu().numpy();hs=bits(h)
            for b in range(len(ctx['indices'])):
                for j in range(values.shape[1]):
                    k=int(np.argmin(pool['value'][:,j]))
                    if values[b,j]>pool['value'][k,j]:
                        pool['value'][k,j]=values[b,j];pool['doc'][k,j]=ctx['indices'][b];pool['position'][k,j]=positions[b,j];pool['h'][k,j]=hs[b,j]
        for l,layer in enumerate(model.model.layers):
            def pre(_m,args,l=l):hidden[ctx['indices'],l]=bits(args[0][:,-1])
            def prenorm(_m,args,l=l):ctx[(l,'h')]=args[0].detach()
            def gate(_m,args,out,l=l):ctx[(l,'G')]=out.detach()
            def value(_m,args,out,l=l):ctx[(l,'V')]=out.detach()
            def act(_m,args,l=l):
                a=args[0].detach();g=ctx.pop((l,'G'));v=ctx.pop((l,'V'));h=ctx.pop((l,'h'));fold=ctx['fold'];ix=ctx['indices'];sel=specs[l]
                for key,x in [('G',g),('V',v),('A',a)]:
                    mm[l][key][ix]=bits(x[:,:,sel]);z=x[:,32:].float().flatten(0,1)
                    sums[fold,l,['G','V','A'].index(key)]+=z.sum(0,dtype=torch.float64)
                    squares[fold,l,['G','V','A'].index(key)]+=(z*z).sum(0,dtype=torch.float64)
                    mins[fold,l,['G','V','A'].index(key)]=torch.minimum(mins[fold,l,['G','V','A'].index(key)],z.amin(0).double())
                    maxs[fold,l,['G','V','A'].index(key)]=torch.maximum(maxs[fold,l,['G','V','A'].index(key)],z.amax(0).double())
                gg=g[:,32:]>0;vv=v[:,32:]>0
                for k,mask in enumerate([gg&vv,(~gg)&(~vv),gg&(~vv),(~gg)&vv]):regimes[fold,l,:,k]+=mask.sum((0,1))
                hh=h[:,32:].float();hsum[fold,l]+=hh.sum((0,1),dtype=torch.float64);hnorm[fold,l]+=hh.norm(dim=-1).sum(dtype=torch.float64)
                for key,x in [('G',g),('A',a)]:
                    picked=x[:,32:,sel].float()
                    for pole,sign in [('pos',1),('neg',-1)]:
                        values,positions=(picked*sign).max(1);positions+=32
                        hp=h[torch.arange(len(ix),device='cuda')[:,None],positions]
                        pool_update(fold,l,key+pole,values*sign,positions,hp)
            handles += [layer.register_forward_pre_hook(pre),layer.post_attention_layernorm.register_forward_pre_hook(prenorm),
                layer.mlp.gate_proj.register_forward_hook(gate),layer.mlp.up_proj.register_forward_hook(value),layer.mlp.down_proj.register_forward_pre_hook(act)]
        def final(_m,args,out):hidden[ctx['indices'],36]=bits(out[:,-1])
        handles.append(model.model.norm.register_forward_hook(final));results=[]
        status('collection','running',done=0,total=2048,random_units=432,all_unit_statistics=350208)
        for start in range(0,len(docs),2):
            ix=list(range(start,min(start+2,len(docs))));fold={'discovery':0,'confirm':1,'lockbox':2}[docs[start]['split']]
            assert all(docs[i]['split']==docs[start]['split'] for i in ix);ctx.update(indices=ix,fold=fold)
            with torch.inference_mode():out=model(input_ids=torch.tensor(np.asarray(raw[ix,:1024]),device='cuda'),use_cache=False,logits_to_keep=1)
            probs=out.logits[:,-1].float().log_softmax(-1)
            for j,i in enumerate(ix):results.append({'doc_index':i,'actual_next_token_id':int(raw[i,1024]),'predicted_next_token_id':int(probs[j].argmax()),'nll':-float(probs[j,int(raw[i,1024])])})
            count[fold]+=len(ix)*992;del out,probs
            if (start+2)%32==0:status('collection','running',done=start+2,total=2048,seconds=round(time.time()-started,1))
        for h in handles:h.remove()
        for l,bykey in mm.items():
            for mmap in bykey.values():mmap.flush()
        hidden.flush()
        np.savez(P.OUT/'population-statistics.npz',count=count,sums=sums.cpu().numpy(),squares=squares.cpu().numpy(),mins=mins.cpu().numpy(),maxs=maxs.cpu().numpy(),regimes=regimes.cpu().numpy(),hsum=hsum.cpu().numpy(),hnorm=hnorm.cpu().numpy())
        for (fold,l,pole),pool in pools.items():
            pool['value']*=(-1 if pole.endswith('neg') else 1);np.savez(P.OUT/f'pool-{fold}-L{l:02d}-{pole}.npz',**pool)
        write_norm=np.stack([layer.mlp.down_proj.weight.float().norm(dim=0).cpu().numpy() for layer in model.model.layers]);np.save(P.OUT/'write-norm.npy',write_norm)
        for l,layer in enumerate(model.model.layers):
            sel=specs[l];np.savez(P.OUT/f'parameters-L{l:02d}.npz',gate=bits(layer.mlp.gate_proj.weight[sel]),up=bits(layer.mlp.up_proj.weight[sel]),
                down=bits(layer.mlp.down_proj.weight[:,sel].T),gamma=bits(layer.post_attention_layernorm.weight))
        assert snapshot(P.MODEL)==pr['model_snapshot']
        manifest={'kind':'real','run_id':P.RUN,'model_snapshot':pr['model_snapshot'],'docs':2048,'tokens':2097152,'counted_per_split':count.tolist(),
            'units':units,'selected_raw_arrays':[{'path':p.name,'sha256':file_sha(p),'bytes':p.stat().st_size} for p in sorted(P.OUT.glob('L??-?.npy'))],
            'other_files':[{'path':p.name,'sha256':file_sha(p),'bytes':p.stat().st_size} for p in [P.OUT/'population-statistics.npz',P.OUT/'hidden_last.npy',P.OUT/'write-norm.npy']],
            'seconds':time.time()-started,'peak_cuda_bytes':torch.cuda.max_memory_allocated(),'snapshot_unchanged':True,'provenance':prov}
        P.save(P.OUT/'collection.json',manifest);P.save(P.OUT/'next-token-observations.json',{'rows':results,'provenance':prov});status('collection',docs=2048,counted_tokens=int(count.sum()),seconds=manifest['seconds'])
if __name__=='__main__':main()

"""Prospective matched natural-query doses, unchanged-weight audit and NI gate."""
import sys,json,time,argparse
from pathlib import Path
import numpy as np
sys.path.insert(0,str(Path(__file__).parent))
import native_mlp_long_materials as P
from native_mlp_long_run import status
from shared.dist_protocol.mechanism_trace import GpuLease,Recorder as BaseRecorder,TraceStore,digest,file_sha,unbits,save_json
from shared.dist_protocol.natural_register_runner import snapshot
from phase2773_w6_loop import paired_interval

class Recorder(BaseRecorder):
    def finish(self,*args,**kwargs):
        d,p=super().finish(*args,**kwargs)
        d['causal_visibility']='Plain natural prefix; query is its last position. No future token, source label or expected answer is supplied to the model.'
        d.pop('trace_id');d['trace_id']=digest(d);save_json(p,d);return d,p

def install(model,group,alpha,position=-1):
    handles=[]
    for l,u in group:
        def hook(_m,args,u=u):
            x=args[0].clone();x[:,position,u]*=1-alpha;return (x,)
        handles.append(model.model.layers[l].mlp.down_proj.register_forward_pre_hook(hook))
    return handles

def interval(values):
    values=np.asarray(values);rng=np.random.default_rng(P.SEED)
    means=values[rng.integers(0,len(values),(10000,len(values)))].mean(1)
    return {'mean':float(values.mean()),'ci95':np.quantile(means,[.025,.975]).tolist()}

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--part',choices=['dose','capability','trace'],required=True);part=parser.parse_args().part
    import torch
    from transformers import AutoTokenizer,AutoModelForCausalLM
    selection=P.read(P.OUT/'selection.json');data=P.read(P.OUT/'documents.json');prov=selection['provenance'];raw=np.load(P.OUT/'input-tokens.npy',mmap_mode='r')
    inputs=P.ROOT/'tests/glm5/result/phase2773_w6_v2/capability-inputs.json'
    contract={'kind':'real','run_id':P.RUN,'part':part,'script_sha256':file_sha(__file__),'selection_sha256':file_sha(P.OUT/'selection.json'),
        'units':selection['units'],'random_units':selection['random_units'],'query_operation':'Only the evaluated query position; past positions unchanged',
        'conditions':['base','target_half','target_full','random_full'],'n':256,'primary_effect':'natural actual-next-token top1 loss at alpha1 >= .10 and target-minus-random loss >= .05; paired bootstrap lower95 bounds >0',
        'secondary':'mean full-vocabulary KL and NLL; descriptive, no unique-neuron mechanism claim',
        'capability_input_sha256':file_sha(inputs),'capability_margin':.02,'provenance':prov}
    P.save(P.OUT/f'{part}-contract.json',contract)
    with GpuLease():
        assert snapshot(P.MODEL)==prov['model_revision'];torch.set_num_threads(4);torch.manual_seed(P.SEED);started=time.time()
        tok=AutoTokenizer.from_pretrained(P.MODEL,local_files_only=True);tok.padding_side='left'
        model=AutoModelForCausalLM.from_pretrained(P.MODEL,local_files_only=True,dtype=torch.bfloat16,device_map='cuda:0',attn_implementation='sdpa').eval().requires_grad_(False)
        def forward(ids,**kw):
            with torch.inference_mode():return model(input_ids=torch.tensor([ids],device='cuda'),use_cache=False,**kw)
        if part=='dose':
            rows=[];logits=[];instrumentation=[];pairs=data['pairs']['lockbox'];status('intervention','running',done=0,total=256)
            for i,pair in enumerate(pairs):
                di,q=pair['a'],pair['position'];ids=np.asarray(raw[di,:1024]);truth=int(raw[di,q+1]);by={};captured={};hh=[]
                # Control capture at the exact query, then bitwise compare with an uninstrumented forward.
                for l,u in selection['units']:
                    def cap(_m,args,l=l,u=u):captured[(l,u)]=float(args[0][0,q,u])
                    hh.append(model.model.layers[l].mlp.down_proj.register_forward_pre_hook(cap))
                o=forward(ids,logits_to_keep=torch.tensor([q],device='cuda'));audit=o.logits[0,-1].detach().clone()
                for h in hh:h.remove()
                maxerr=0.
                for l,u in selection['units']:
                    ix=[r['unit'] for r in data['units'] if r['layer']==l].index(u);a=np.load(P.OUT/f'L{l:02d}-A.npy',mmap_mode='r')
                    maxerr=max(maxerr,abs(captured[(l,u)]-float(unbits(a[di,q,ix]))))
                for name,alpha,group in [('base',0,[]),('target_half',.5,selection['units']),('target_full',1,selection['units']),('random_full',1,selection['random_units'])]:
                    handles=install(model,group,alpha,q)
                    try:o=forward(ids,logits_to_keep=torch.tensor([q],device='cuda'))
                    finally:
                        for h in handles:h.remove()
                    v=o.logits[0,-1];lp=v.float().log_softmax(-1);by[name]=lp.detach().clone()
                    logits.append(v.contiguous().view(torch.uint16).cpu().numpy())
                    row={'pair_index':i,'doc_index':di,'position':q,'condition':name,'expected_token_id':truth,'top1':int(lp.argmax()),'nll':-float(lp[truth])}
                    row['correct']=row['top1']==truth;rows.append(row)
                    if name=='base':instrumentation.append({'pair_index':i,'hook_logits_bitwise_equal':bool(torch.equal(v,audit)),'batch2_to_batch1_selected_A_max_absolute':maxerr})
                for row in rows[-4:]:row['KL_from_base']=float((by['base'].exp()*(by['base']-by[row['condition']])).sum())
                if (i+1)%32==0:status('intervention','running',done=i+1,total=256)
            np.save(P.OUT/'dose-logits.npy',np.stack(logits));by={c:[r for r in rows if r['condition']==c] for c in contract['conditions']};base=by['base']
            effects={c:{'accuracy':float(np.mean([r['correct'] for r in rr])),
                'loss':interval([b['correct']-r['correct'] for b,r in zip(base,rr)]),
                'KL':interval([r['KL_from_base'] for r in rr]),'NLL_shift':interval([r['nll']-b['nll'] for b,r in zip(base,rr)])} for c,rr in by.items()}
            specificity=interval([r['correct']-t['correct'] for r,t in zip(by['random_full'],by['target_full'])]);loss=effects['target_full']['loss']
            result={'kind':'real','run_id':P.RUN,'rows':rows,'effects':effects,'specificity':specificity,
                'supported':bool(loss['mean']>=.1 and loss['ci95'][0]>0 and specificity['mean']>=.05 and specificity['ci95'][0]>0),
                'instrumentation':instrumentation,'seconds':time.time()-started,'provenance':prov}
            P.save(P.OUT/'dose-result.json',result);status('intervention',supported=result['supported'],effects=effects,specificity=specificity)
        elif part=='capability':
            qs=P.read(inputs);ids=[tok.encode(x,add_special_tokens=False)[0] for x in 'ABCDE'];rows={};status('capability','running',done=0,total=2*len(qs))
            for condition in ['base','selected_units']:
                handles=install(model,selection['units'],1.) if condition=='selected_units' else [];records=[]
                try:
                    for start in range(0,len(qs),4):
                        chunk=qs[start:start+4];tokens=[]
                        for q in chunk:
                            text=q['question']+'\n'+'\n'.join(f'{s}. {choice}' for s,choice in zip('ABCDE',q['choices']))+'\n请只回答正确选项字母。'
                            prompt=tok.apply_chat_template([{'role':'user','content':text}],tokenize=False,add_generation_prompt=True,enable_thinking=False);tokens.append(tok.encode(prompt,add_special_tokens=False))
                        batch={k:v.cuda() for k,v in tok.pad({'input_ids':tokens},padding=True,return_tensors='pt').items()}
                        with torch.inference_mode():o=model(**batch,use_cache=False,logits_to_keep=1)
                        for j,q in enumerate(chunk):
                            scores=o.logits[j,-1,ids[:len(q['choices'])]].float().cpu();pred='ABCDE'[int(scores.argmax())]
                            records.append({'id':q['id'],'prediction':pred,'answer':q['answer'],'correct':pred==q['answer'],'source':q['source'],'gate_eligible':q['gate_eligible'],'choice_logits':scores.tolist(),'input_tokens':len(tokens[j])})
                        if start%400==0:status('capability','running',condition=condition,done=start+len(chunk),total=len(qs))
                finally:
                    for h in handles:h.remove()
                rows[condition]=records;P.save(P.OUT/f'capability-{condition}.json',records)
            result=paired_interval([x['correct'] for x in rows['base']],[x['correct'] for x in rows['selected_units']],np.asarray([q['gate_eligible'] for q in qs]))
            result.update(kind='real',run_id=P.RUN,scope='Repeated old keyed pool, new16unit current-query operation; 140 reference-only excluded',seconds=time.time()-started,provenance=prov)
            P.save(P.OUT/'capability-result.json',result);status('capability',result=result)
        else:
            # Text-independent fixed representative: top confirm-selected unit and first four lockbox pairs, both sides.
            l,u=selection['units'][0];records=[];store=TraceStore()
            for i,pair in enumerate(data['pairs']['lockbox'][:4]):
                for side in ['a','b']:
                    di=pair[side];doc=data['docs'][di];q=pair['position'];ids=raw[di,:q+1].tolist();text=tok.decode(ids)
                    item={'id':f'{P.RUN}:pair{i}:{side}','entity':doc.get('title') or doc['doc_id'],'scope':'自然长文 · 同token/同位置配对','split':'lockbox','token_ids':ids,'text':text,'prompt':text}
                    with Recorder(model,[q],P.OUT/'native'/f'pair{i}-{side}',deep=True) as rec:o=forward(ids,logits_to_keep=1,output_hidden_states=True)
                    d,p=rec.finish(o,item,tok,prov['model_revision'],P.RUN,prov);store.register(p)
                    records.append({'trace_id':d['trace_id'],'pair_index':i,'side':side,'doc_index':di,'position':q,'layer':l,'unit':u,'n_tokens':len(ids),'max_attention_relative_l2':max(v['attention_relative_l2'] for v in d['reconstruction'].values())})
                    del o;status('validation','running',done=len(records),total=8)
            assert max(r['max_attention_relative_l2'] for r in records)<.05
            P.save(P.OUT/'trace-examples.json',{'kind':'real','run_id':P.RUN,'rows':records,'provenance':prov});status('validation',traces=8)
        assert snapshot(P.MODEL)==prov['model_revision']

